// handleLifecycleTurnStart handles turn start: captures pre-prompt state,
// ensures strategy setup, initializes session.
// entireTrailContextInjection is the one-time, model-facing pointer Entire
// injects on the first turn of a session. It points at `entire agent-help` for
// the full flag/subcommand surface — fetched on demand so that surface never goes
// stale here as it grows — and adds only a small, stable behavioral invariant an
// agent must know even if it never drills in: commits auto-capture checkpoints,
// the two stable query anchors (`why`, `checkpoint search`) for recovering intent
// before edits, and that setup/destructive commands belong to the user. It also
// names the auto-detected repo (from the already-loaded session scope, no IO) and
// the standing rule that the agent is inside the repo and must never ask the user
// for the repo name. Kept terse: it costs context-window tokens on the first turn
// of every session.
func entireTrailContextInjection(scope trailEnablementScope) string {
	repo := ""
	if scope.Forge != "" && scope.Owner != "" && scope.Repo != "" {
		repo = trailEnablementRepoKey(scope.Forge, scope.Owner, scope.Repo)
	}
	var b strings.Builder
	b.WriteString("Entire is enabled for this repo. Run `entire agent-help` to see what entire does and which subcommand to use, then `entire agent-help <command>` for that command's exact, current flags. ")
	b.WriteString("Commits automatically capture the AI session as a checkpoint, so never create checkpoints by hand — just commit normally. Before large edits, `entire why <file>:<line>` and `entire checkpoint search` recover the intent behind existing code. Leave setup and destructive commands (enable, disable, clean, rewind, auth) to the user. ")
	// Mirror agentHelpRepoBlock's defense-in-depth: this string is injected raw
	// into the agent's model context (no escaping), so a repo key carrying control
	// characters (e.g. an <sessionID>.trail-scope.json cache written by a pre-fix
	// binary, or tampered) degrades to the generic message rather than reaching
	// that sink.
	if repo != "" && strings.IndexFunc(repo, unicode.IsControl) < 0 {
		b.WriteString("This repo is auto-detected from the git origin remote as ")
		b.WriteString(repo)
		b.WriteString("; you are already inside it, so never ask the user for the repo name.")
	} else {
		b.WriteString("Entire auto-detects the repo from the git origin remote, so never ask the user for the repo name.")
	}
	return b.String()
}

// emitContextInjection writes ag's native context-injection payload to stdout
// when ag injects at event.Type, trails are enabled for the repo on the API,
// and this session has not been injected yet. Best-effort: an injection failure
// never fails the hook.
func emitContextInjection(ctx context.Context, ag agent.Agent, event *agent.Event) {
	injector, ok := agent.AsContextInjector(ag)
	if !ok || injector.InjectionEvent() != event.Type || event.SessionID == "" {
		return
	}
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())

	// Unknown cache leaves the session retryable.
	scope, scopeOK, scopeErr := loadTrailEnablementScopeHint(ctx, event.SessionID)

// Package experimental gates the visibility of experimental CLI commands.
//
// Experimental commands stay fully runnable in every build; this package only
// controls whether they appear in `entire help`. Developer builds (go build,
// go run, mise) show them, grouped under an "Experimental commands:" help
// section. Release builds (GoReleaser) hide them.
package experimental

import "github.com/spf13/cobra"

// Visible controls whether experimental commands are shown in help. It is
// stamped by GoReleaser via ldflags
// (-X github.com/entireio/cli/cmd/entire/cli/experimental.Visible=false)
// to hide them in shipped binaries. It defaults to "true", so every
// non-release build (go build, go run, mise) shows them. The commands remain
// experimental and fully runnable regardless of this flag — it only toggles
// visibility.
var Visible = "true"

// IsVisible reports whether experimental commands are shown in help.
func IsVisible() bool { return Visible != "false" }

// GroupID is the cobra group experimental commands are filed under.
const GroupID = "experimental"

const groupTitle = "Experimental commands:"

// Register adds child under parent as an experimental command.
//
// When experimental commands are visible, child is filed under parent's
// "Experimental commands:" help group (registering the group on parent once).
// When hidden, child is marked Hidden and left ungrouped — so release help
// never carries an empty group header, and cobra never references a group ID
// that was not registered.
//
// Register overrides any Hidden value the child's constructor set, so callers
// do not need to touch the constructors (including ones in other packages).
func Register(parent, child *cobra.Command) {
	if IsVisible() {
		if !parent.ContainsGroup(GroupID) {
			parent.AddGroup(&cobra.Group{ID: GroupID, Title: groupTitle})
		}
		child.Hidden = false
		child.GroupID = GroupID
	} else {
		child.Hidden = true
		child.GroupID = ""
	}
	parent.AddCommand(child)
}

	SilenceUsage:  true,
	// Hide completion command from help but keep it functional
	CompletionOptions: cobra.CompletionOptions{
		HiddenDefaultCmd: true,
	},
	PersistentPostRun: func(cmd *cobra.Command, _ []string) {
		// Skip for hidden commands (walk parent chain — Cobra doesn't propagate Hidden)
		for c := cmd; c != nil; c = c.Parent() {
			if c.Hidden {
				return
			}
		}

		// Load settings once for telemetry and version check
		var telemetryEnabled *bool
		settings, err := LoadEntireSettings(cmd.Context())
		if err == nil {
			telemetryEnabled = settings.Telemetry
		}

		// Check if telemetry is enabled
		if telemetryEnabled != nil && *telemetryEnabled {
			// Use detached tracking (non-blocking)
			installedAgents := GetAgentsWithHooksInstalled(cmd.Context())
			agentStr := JoinAgentNames(installedAgents)
			telemetry.TrackCommandDetached(cmd, agentStr, settings.Enabled, versioninfo.Version)
		}

		// Version check and notification (synchronous with 2s timeout)
		// Runs AFTER command completes to avoid interfering with interactive modes.
		// Stderr, never stdout: this hook also fires after --json commands whose
		// stdout is piped into jq or captured by scripts — a notice on stdout
		// corrupts that output while staying invisible in the caller's logs.
		versioncheck.CheckAndNotify(cmd.Context(), cmd.ErrOrStderr(), versioninfo.Version)
	},
	RunE: func(cmd *cobra.Command, _ []string) error {
		ctx := cmd.Context()
		// If we're in a git repo but Entire isn't set up yet, start the setup flow
		if _, err := paths.WorktreeRoot(ctx); err == nil && !settings.IsSetUpAny(ctx) {
			return runSetupFlow(ctx, cmd.OutOrStdout(), EnableOptions{})
		}
		return cmd.Help()
	},
}

// Help groups; AddGroup order is display order in `entire --help`.
cmd.AddGroup(
	&cobra.Group{ID: groupSetup, Title: "Entire Setup:"},
	&cobra.Group{ID: groupSessions, Title: "Sessions & Checkpoints:"},
	&cobra.Group{ID: groupAccount, Title: "Account:"},
	&cobra.Group{ID: groupControlPlane, Title: "Control Plane:"},
)

// Noun groups (canonical homes for subcommands).
cmd.AddCommand(inGroup(newSessionsCmd(), groupSessions))        // 'session' (with 'sessions' as Cobra alias)
cmd.AddCommand(inGroup(newCheckpointGroupCmd(), groupSessions)) // 'checkpoint' / 'cp' / 'checkpoints'
experimental.Register(cmd, newTokensGroupCmd())                 // 'tokens' (experimental)
cmd.AddCommand(inGroup(newAgentGroupCmd(), groupSetup))         // 'agent'
cmd.AddCommand(inGroup(newAuthCmd(), groupAccount))             // 'auth'
cmd.AddCommand(inGroup(newDoctorCmd(), groupSetup))             // 'doctor' (group: trace/logs/bundle)

